/// Append a `help[N]:` block to an existing string in-place.
pub fn append_hints(out: &mut String, hints: &[Hint]) {
    if hints.is_empty() {
        return;
    }
    out.push_str("help[");
    out.push_str(&hints.len().to_string());
    out.push_str("]:\n");
    for hint in hints {
        out.push_str("  ");
        out.push_str(hint.as_str());
        out.push('\n');
    }
}

